import { useMemo, useRef, useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import { Link, useSearchParams } from 'react-router-dom';

import { getFeed, type FeedItem } from '@/entities/feed';
import { getCatalogCategories, getCategoryHref } from '@/shared/catalog';
import { PLATFORM_SECTION } from '@/shared/platform';
import type { CatalogCategory } from '@/shared/types/catalog-category';
import { CombinedItemsGrid } from '@/widgets/CombinedFeed';
import { CatalogControls } from '@/widgets/Catalog/components/CatalogControls';
import type { CatalogPriceFilterValue } from '@/widgets/Catalog/components/CatalogControls/components/CatalogFilters/types/catalog-filters';
import type { CatalogSortRule } from '@/widgets/Catalog/components/CatalogControls/components/CatalogSorting/types/catalog-sorting';
import { filterGlobalSearchCategories } from '@/widgets/GlobalSearch/logic/filter-global-search-categories';
import { filterGlobalSearchSections } from '@/widgets/GlobalSearch/logic/filter-global-search-sections';
import { getSearchTokens, normalizeSearchValue } from '@/widgets/GlobalSearch/logic/normalize-search-value';

function getItem(item: FeedItem) {
  return item.type === 'PRODUCT' ? item.product : item.ad;
}

function getItemCategory(item: FeedItem) {
  return getItem(item).category;
}

function matchesQuery(item: FeedItem, query: string) {
  const tokens = getSearchTokens(query);

  if (!tokens.length) {
    return false;
  }

  const entity = getItem(item);
  const searchableValue = normalizeSearchValue(
    `${entity.title} ${entity.description ?? ''}`,
  );

  return tokens.every((token) => searchableValue.includes(token));
}

function SearchListings({
  items,
  query,
}: {
  items: FeedItem[];
  query: string;
}) {
  const containerRef = useRef<HTMLDivElement>(null);
  const matchingItems = useMemo(
    () => items.filter((item) => matchesQuery(item, query)),
    [items, query],
  );
  const prices = matchingItems.map((item) => getItem(item).price);
  const initialPriceFilter = {
    from: prices.length ? Math.min(...prices) : 0,
    to: prices.length ? Math.max(...prices) : 0,
  };
  const [priceFilter, setPriceFilter] =
    useState<CatalogPriceFilterValue>(initialPriceFilter);
  const [selectedCategoryIds, setSelectedCategoryIds] = useState<string[]>([]);
  const [sortRules, setSortRules] = useState<CatalogSortRule[]>([]);

  const categoryOptions = useMemo(() => {
    const categories = new Map<
      string,
      { id: string; name: string; productsCount: number }
    >();

    matchingItems.forEach((item) => {
      const category = getItemCategory(item);
      if (!category) return;

      const current = categories.get(category.id);
      categories.set(category.id, {
        id: category.id,
        name: category.name,
        productsCount: (current?.productsCount ?? 0) + 1,
      });
    });

    return Array.from(categories.values()).sort((first, second) =>
      first.name.localeCompare(second.name, 'ru'),
    );
  }, [matchingItems]);

  const visibleItems = useMemo(() => {
    const filteredItems = matchingItems.filter((item) => {
      const entity = getItem(item);
      const category = getItemCategory(item);

      return (
        entity.price >= priceFilter.from &&
        entity.price <= priceFilter.to &&
        (!selectedCategoryIds.length ||
          (category && selectedCategoryIds.includes(category.id)))
      );
    });

    return [...filteredItems].sort((first, second) => {
      for (const rule of sortRules) {
        const firstEntity = getItem(first);
        const secondEntity = getItem(second);
        const firstValue =
          rule.field === 'category'
            ? getItemCategory(first)?.name ?? ''
            : firstEntity[rule.field];
        const secondValue =
          rule.field === 'category'
            ? getItemCategory(second)?.name ?? ''
            : secondEntity[rule.field];
        const comparison = String(firstValue).localeCompare(
          String(secondValue),
          'ru',
          { numeric: true },
        );

        if (comparison !== 0) {
          return rule.direction === 'desc' ? -comparison : comparison;
        }
      }

      return 0;
    });
  }, [
    matchingItems,
    priceFilter,
    selectedCategoryIds,
    sortRules,
  ]);

  return (
    <section className="space-y-5">
      <div className="flex flex-wrap items-baseline justify-between gap-3">
        <h2 className="text-xl font-semibold">Товары и объявления</h2>
        <span className="text-sm text-muted-foreground">
          Найдено: {visibleItems.length}
        </span>
      </div>

      <div
        ref={containerRef}
        className="grid gap-6 lg:grid-cols-[280px_minmax(0,1fr)]"
      >
        <CatalogControls
          products={matchingItems.map((item) => ({
            price: getItem(item).price,
          }))}
          priceFilter={priceFilter}
          selectedCategoryIds={selectedCategoryIds}
          sortRules={sortRules}
          subcategoryOptions={categoryOptions}
          containerRef={containerRef}
          onPriceFilterChange={setPriceFilter}
          onSelectedCategoryIdsChange={setSelectedCategoryIds}
          onSortRulesChange={setSortRules}
        />

        {visibleItems.length ? (
          <CombinedItemsGrid items={visibleItems} compact />
        ) : (
          <div className="rounded-2xl border border-dashed border-border p-6 text-center text-sm text-muted-foreground">
            По вашему запросу ничего не найдено.
          </div>
        )}
      </div>
    </section>
  );
}

function AuxiliaryResults({
  query,
  marketCategories,
  adsCategories,
}: {
  query: string;
  marketCategories: CatalogCategory[];
  adsCategories: CatalogCategory[];
}) {
  const marketResults = filterGlobalSearchCategories(marketCategories, query);
  const adsResults = filterGlobalSearchCategories(adsCategories, query);
  const sectionResults = filterGlobalSearchSections(query);
  const categoryResults = [
    ...marketResults.map((category) => ({
      category,
      categories: marketCategories,
      section: PLATFORM_SECTION.MARKET,
    })),
    ...adsResults.map((category) => ({
      category,
      categories: adsCategories,
      section: PLATFORM_SECTION.ADS,
    })),
  ];

  return (
    <section className="space-y-5">
      <div className="space-y-3">
        <h2 className="text-sm font-semibold">Категории</h2>

        <div className="flex flex-wrap gap-2">
          {categoryResults.map(({ category, categories, section }) => (
            <Link
              key={`${section}-${category.id}`}
              to={getCategoryHref(categories, category.id, section)}
              className="rounded-full border border-border bg-background px-3 py-1.5 text-sm transition-colors hover:border-ring hover:bg-muted"
            >
              {category.name}
              <span className="ml-1.5 text-xs text-muted-foreground">
                {section === PLATFORM_SECTION.MARKET ? 'Маркет' : 'Доска'}
              </span>
            </Link>
          ))}

          {!categoryResults.length && (
            <span className="text-sm text-muted-foreground">
              Совпадений не найдено.
            </span>
          )}
        </div>
      </div>

      <div className="space-y-3">
        <h2 className="text-sm font-semibold">Разделы</h2>

        <div className="flex flex-wrap gap-2">
          {sectionResults.map((section) => (
            <Link
              key={section.id}
              to={section.href}
              className="rounded-full border border-border bg-background px-3 py-1.5 text-sm transition-colors hover:border-ring hover:bg-muted"
            >
              {section.title}
            </Link>
          ))}

          {!sectionResults.length && (
            <span className="text-sm text-muted-foreground">
              Совпадений не найдено.
            </span>
          )}
        </div>
      </div>
    </section>
  );
}

export function SearchPage() {
  const [searchParams] = useSearchParams();
  const query = searchParams.get('q')?.trim() ?? '';

  const {
    data: feedItems = [],
    isPending: isFeedPending,
    isError: isFeedError,
  } = useQuery({
    queryKey: ['search-feed'],
    queryFn: getFeed,
    enabled: Boolean(query),
  });
  const { data: marketCategories = [] } = useQuery({
    queryKey: ['global-search-categories', PLATFORM_SECTION.MARKET],
    queryFn: () => getCatalogCategories({ section: PLATFORM_SECTION.MARKET }),
    enabled: Boolean(query),
  });
  const { data: adsCategories = [] } = useQuery({
    queryKey: ['global-search-categories', PLATFORM_SECTION.ADS],
    queryFn: () => getCatalogCategories({ section: PLATFORM_SECTION.ADS }),
    enabled: Boolean(query),
  });

  if (!query) {
    return (
      <div className="rounded-2xl border border-dashed border-border p-8 text-center">
        <h1 className="text-2xl font-semibold">Поиск</h1>
        <p className="mt-2 text-sm text-muted-foreground">
          Введите поисковый запрос в строке поиска.
        </p>
      </div>
    );
  }

  return (
    <div className="space-y-8">
      <header>
        <h1 className="text-2xl font-semibold">
          Поиск по запросу «{query}»
        </h1>
      </header>

      <AuxiliaryResults
        query={query}
        marketCategories={marketCategories}
        adsCategories={adsCategories}
      />

      {isFeedPending ? (
        <p className="text-sm text-muted-foreground">Ищем объявления и товары...</p>
      ) : isFeedError ? (
        <p className="text-sm text-destructive">
          Не удалось загрузить результаты поиска.
        </p>
      ) : (
        <SearchListings key={query} items={feedItems} query={query} />
      )}
    </div>
  );
}

